    function applyTheme(name) {
        styleEl.innerHTML = themes[name] || '';
        localStorage.setItem('from-custom-theme', name); // Сохраняем выбор
    }

    // Восстанавливаем сохраненную тему при запуске
    applyTheme(localStorage.getItem('from-custom-theme') || 'clear');

    // Функция генерации карточки (кнопки)
    function createThemeCard(config) {
        const card = document.createElement('div');
        card.className = 'masyka-btn-press from-theme-btn';
        card.style.cssText = `position: relative; width: 90px; padding: 10px 6px; border-radius: 14px; background-color: #1a1a1a; border: 2.5px solid ${config.c1}; cursor: pointer; display: flex; flex-direction: column; align-items: center; gap: 6px; flex-shrink: 0;`;

        card.innerHTML = `
            <div style="width: 44px; height: 44px; border-radius: 12px; background-color: #2b2b2b; display: flex; align-items: center; justify-content: center; font-size: 22px;">${config.emoji}</div>
            <div style="display: flex; gap: 3px;">
                <div style="width: 12px; height: 12px; border-radius: 50%; background-color: ${config.c1}; border: 1px solid rgba(255,255,255,0.1);"></div>
                <div style="width: 12px; height: 12px; border-radius: 50%; background-color: ${config.c2}; border: 1px solid rgba(255,255,255,0.1);"></div>
            </div>
            <div style="font-size: 11px; font-weight: 600; color: #fff; text-align: center;">${config.name}</div>
        `;

        // При клике применяем тему
        card.onclick = () => applyTheme(config.id);
        return card;
    }

    // Слушатель изменений DOM (ждем, когда откроются "Настройки")
    const observer = new MutationObserver(() => {
        // Ищем контейнер с темами (ориентируемся по стандартной теме "Классика")
        const themeContainer = Array.from(document.querySelectorAll('div')).find(el => 
            el.textContent === 'Классика' && el.style.fontSize === '11px'
        )?.parentElement?.parentElement;

        // Если меню открыто и наши кнопки еще не добавлены
        if (themeContainer && !themeContainer.querySelector('.from-theme-btn')) {
            // Добавляем все наши темы в ленту
            themeConfigs.forEach(config => {
                themeContainer.appendChild(createThemeCard(config));
            });

            // Если пользователь кликнет на любую СТАНДАРТНУЮ тему, мы отключаем свои стили
            const standardThemes = themeContainer.querySelectorAll('.masyka-btn-press:not(.from-theme-btn)');
            standardThemes.forEach(btn => {
                btn.addEventListener('click', () => applyTheme('clear'));
            });
        }
    });

    // Запускаем слежение
    observer.observe(document.body, { childList: true, subtree: true });
})();
]]

