-- @name Автопереводчик
-- @description Переводит приложение в реальном времени. Фикс застревания языка.
-- @icon 🌍

app:showToast("Переводчик запущен. Проверка системы...")

local jsCode = [=[
(function() {
    if (window.__masykaTranslatorActive) return;
    window.__masykaTranslatorActive = true;

    // УБИЙЦА GOOGLE COOKIES (уничтожает привязку языка)
    function nukeGoogleTranslate() {
        localStorage.setItem('masyka_lang', 'ru');

        const host = window.location.hostname;
        const domains = [
            host, 
            '.' + host, 
            'xn--80aa3ag0a0e.xn--p1ai', 
            '.xn--80aa3ag0a0e.xn--p1ai',
            'маська.рф', 
            '.маська.рф',
            '' // без домена
        ];

        // Проходимся по всем доменам и путям и удаляем куки googtrans
        domains.forEach(d => {
            const domainStr = d ? `domain=${d};` : '';
            document.cookie = `googtrans=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/; ${domainStr}`;
        });

        // Удаляем сам скрипт гугла из кода, чтобы он не успел вернуть куки перед обновлением
        document.querySelectorAll('script[src*="translate.google.com"], #google_translate_element, .skiptranslate').forEach(el => el.remove());

        // Жесткая перезагрузка со сбросом кэша (чтобы React отрисовал чистый интерфейс)
        // Убираем старые параметры сброса, чтобы не было бесконечного цикла, и добавляем новый
        const url = new URL(window.location.href);
        url.searchParams.set('lang_reset', Date.now()); 
        window.location.href = url.toString();
    }

    // АВТО-ЛЕЧЕНИЕ БАГА
    // Проверяем: если в LocalStorage стоит 'ru', но кука googtrans существует — юзер застрял. Лечим.
    const currentLang = localStorage.getItem('masyka_lang') || 'ru';
    const hasGoogleCookie = document.cookie.includes('googtrans=') && !document.cookie.includes('googtrans=/ru/ru');

    if (currentLang === 'ru' && hasGoogleCookie) {
        console.log("Обнаружен застрявший перевод. Лечим...");
        nukeGoogleTranslate();
        return; // Останавливаем выполнение, ждем перезагрузки
    }

    // Очищаем URL от мусора после сброса (чтобы было красиво)
    if (window.location.search.includes('lang_reset')) {
        const cleanUrl = window.location.protocol + "//" + window.location.host + window.location.pathname;
        window.history.replaceState({}, document.title, cleanUrl);
    }

    // Если всё нормально и выбран НЕ русский, загружаем переводчик
    if (currentLang !== 'ru') {
        const gtDiv = document.createElement('div');
        gtDiv.id = 'google_translate_element';
        gtDiv.style.display = 'none';
        document.body.appendChild(gtDiv);

        const gtInitScript = document.createElement('script');
        gtInitScript.innerHTML = `
            function googleTranslateElementInit() {
                new google.translate.TranslateElement({
                    pageLanguage: 'ru', 
                    autoDisplay: false
                }, 'google_translate_element');
            }
        `;
        document.head.appendChild(gtInitScript);

        const gtScript = document.createElement('script');
        gtScript.src = 'https://translate.google.com/translate_a/element.js?cb=googleTranslateElementInit';
        document.head.appendChild(gtScript);

        // Прячем мусор от гугла
        const style = document.createElement('style');
        style.innerHTML = `
            body { top: 0 !important; position: static !important; }
            .skiptranslate, #goog-gt-tt { display: none !important; }
            font { background: transparent !important; box-shadow: none !important; color: inherit !important; }
        `;
        document.head.appendChild(style);
    }

    // Применение языка из меню
    window.__applyTranslation = function(langCode) {
        localStorage.setItem('masyka_lang', langCode);

        if (langCode === 'ru') {
            nukeGoogleTranslate();
            return;
        }

        // Если переводчик еще не вставлен на страницу (выбрали язык впервые), перезагружаем страницу, чтобы он загрузился
        if (!document.getElementById('google_translate_element')) {
            window.location.reload();
            return;
        }

        const selectField = document.querySelector(".goog-te-combo");
        if (selectField) {
            selectField.value = langCode;
            selectField.dispatchEvent(new Event('change'));
        } else {
            setTimeout(() => window.__applyTranslation(langCode), 500);
        }
    };

    // Отрисовка меню в настройках
    function injectSettingsUI() {
        if (document.getElementById('masyka-translator-ui')) return;

        const h1Elements = Array.from(document.querySelectorAll('h1'));
        const settingsTitle = h1Elements.find(el => el.textContent === 'Настройки');
        if (!settingsTitle) return;

        const settingsContainer = settingsTitle.parentElement.nextElementSibling;
        if (!settingsContainer) return;

        const actualLang = localStorage.getItem('masyka_lang') || 'ru';

        // notranslate защищает меню от перевода
        const uiHTML = `
            <div id="masyka-translator-ui" class="notranslate" style="display: flex; flex-direction: column; gap: 10px; margin-bottom: 10px;">
                <div style="font-size: 11px; font-weight: 500; color: rgb(122, 122, 154); padding: 8px 6px 4px; text-transform: uppercase; letter-spacing: 0.05em;">
                    Переводчик
                </div>
                <div style="background-color: rgb(22, 33, 62); border-radius: 14px; padding: 10px 16px; display: flex; align-items: center; justify-content: space-between; gap: 12px;">
                    <div style="flex: 1 1 0%;">
                        <div style="font-size: 15px; font-weight: 600; color: rgb(224, 224, 224);">Язык приложения</div>
                        <div style="font-size: 12px; color: rgb(122, 122, 154); margin-top: 2px;">Переводит интерфейс и чаты</div>
                    </div>
                    <select id="masyka-lang-select" style="background-color: rgb(15, 52, 96); color: rgb(224, 224, 224); font-size: 14px; font-weight: 600; padding: 6px 10px; border-radius: 10px; border: none; outline: none; cursor: pointer;">
                        <option value="ru">Русский (Оригинал)</option>
                        <option value="en">English</option>
                        <option value="uk">Українська</option>
                        <option value="kk">Қазақша</option>
                        <option value="be">Беларуская</option>
                        <option value="es">Español</option>
                        <option value="zh-CN">中文 (Китайский)</option>
                    </select>
                </div>
            </div>
        `;

        settingsContainer.insertAdjacentHTML('afterbegin', uiHTML);

        const selectElement = document.getElementById('masyka-lang-select');
        selectElement.value = actualLang;

        selectElement.addEventListener('change', (e) => {
            window.__applyTranslation(e.target.value);
        });
    }

    const observer = new MutationObserver(() => {
        injectSettingsUI();
    });
    observer.observe(document.body, { childList: true, subtree: true });

})();
]=]

app:executeJs(jsCode)
